<script setup>
import {ref,computed,onUnmounted,watch} from 'vue';
import {selectFolder,prepareCopy} from './localRepository.js';
const token=ref(''), connected=ref(false), busy=ref(false),error=ref(''),notice=ref(''),tab=ref('Inicio');
const catalog=ref({expert:[],board:[],project:[],session:[],context:[],skill:[],artifact:[],repository:[],connection:[]});
const memoryRecords=ref([]),approvedMemoryRecords=ref([]);
const expertSection=ref('content'), advanced=ref(false), showPanelists=ref(false);
const localFolderInput=ref(null),localSelection=ref(null),localSelectedPaths=ref([]),localConsent=ref(false),localCopies=ref([]),localProgress=ref('');
const localRequestedSession=new URLSearchParams(window.location.search).get('local_repository_session');
function clearLocalSelection(){localSelection.value=null;localSelectedPaths.value=[];localConsent.value=false;if(localFolderInput.value)localFolderInput.value.value='';}
function chooseLocalFolder(event){const chosen=Array.from(event.target.files||[]);clearLocalSelection();error.value='';try{localSelection.value=selectFolder(chosen);localSelectedPaths.value=localSelection.value.entries.map(e=>e.path);}catch(e){error.value=e.message;}}
async function refreshLocalCopies(){localCopies.value=session.value?await api('/sessions/'+session.value+'/local-repositories'):[];}
async function shareLocalCopy(){await action(async()=>{localProgress.value='Revisando archivos en este navegador…';try{const copy=await prepareCopy(localSelection.value,localSelectedPaths.value);localProgress.value='Compartiendo la copia autorizada…';await api('/sessions/'+session.value+'/local-repositories',{name:copy.name,files:copy.files,partial:copy.partial,consent:localConsent.value,retention_hours:24});await refreshLocalCopies();notice.value='Copia compartida: '+copy.files.length+' archivos. '+copy.blocked+' omitidos por posibles claves. Ya puede volver a su chat y pedir a Vitruvius que consulte el código.';clearLocalSelection();}finally{localProgress.value='';}});}
async function disconnectLocalCopy(id){await action(async()=>{await api('/sessions/'+session.value+'/local-repositories/'+id,undefined,'DELETE');await refreshLocalCopies();notice.value='Copia desconectada. Las citas que ya formen parte de conversaciones conservan la retención del historial.';});}

const displayTab=computed(()=>({Inicio:'Su consejo de expertos',Contexto:'Documentos',Decisiones:'Especificaciones'})[tab.value]||tab.value);
const originalLinks=ref({});
async function sourceOriginal(id){await action(async()=>{originalLinks.value[id]=(await api('/contexts/'+id+'/original')).url;});}
const referenceTitle=ref(''),referenceAuthor=ref(''),referenceKind=ref('article'),referenceUrl=ref(''),referenceConsent=ref(false),activeReference=ref(null),referenceText=ref(''),referencePdf=ref(null),referencePdfInput=ref(null);
const expertReferences=computed(()=>catalog.value.reference?.filter(r=>r.expert_id===foundationExpert.value)||[]);
const expertProfiles=computed(()=>catalog.value.expert_profile?.filter(r=>r.expert_id===foundationExpert.value).slice().reverse()||[]);
const referenceNames={article:'Artículo',x_post:'Publicación de X',pdf:'PDF',youtube:'Video de YouTube'};
const referenceStatus=r=>r.content_available?(r.foundation_role==='primary'?'Fundamento primario revisado':r.foundation_role==='complementary'?'Bibliografía complementaria revisada':r.source_reviewed?'Contenido revisado · pendiente asignar':'Contenido incorporado · pendiente revisar'):({registered:'Enlace registrado · sin contenido',queued:'Importando contenido',requires_content:'Requiere texto, transcripción o PDF',awaiting_upload:'Esperando PDF',processed:'Contenido incorporado'})[r.status]||r.status;
async function librarySession(){if(!board.value)throw Error('Seleccione un consejo.');const created=await api('/library-session?board_id='+encodeURIComponent(board.value),{});await refresh();return created.id;}
async function registerReference(){await action(async()=>{const r=await api('/experts/'+foundationExpert.value+'/references',{title:referenceTitle.value.trim(),author:referenceAuthor.value.trim(),kind:referenceKind.value,url:referenceUrl.value.trim()||null});activeReference.value=r.id;referenceTitle.value='';referenceUrl.value='';await refresh();notice.value='Referencia guardada. El enlace aún no cuenta como evidencia; incorpore su contenido y revise el fundamento.';});}
async function importReference(id){await action(async()=>{await api('/references/'+id+'/import',{session_id:await librarySession(),permanent_consent:referenceConsent.value});await refresh();notice.value='Revise el estado de la fuente. Un enlace sin contenido no habilita al experto.';});}
async function attachReferenceContent(){await action(async()=>{const sid=await librarySession();if(referencePdf.value){const d=await api('/references/'+activeReference.value+'/upload',{session_id:sid,permanent_consent:referenceConsent.value});const form=new FormData();Object.entries(d.upload.fields).forEach(([k,v])=>form.append(k,v));form.append('file',referencePdf.value);const r=await fetch(d.upload.url,{method:'POST',body:form});if(!r.ok)throw Error('No se pudo cargar el PDF');await api('/contexts/'+d.document_id+'/finalize',{});referencePdf.value=null;if(referencePdfInput.value)referencePdfInput.value.value='';}else{await api('/references/'+activeReference.value+'/text',{session_id:sid,permanent_consent:referenceConsent.value,text:referenceText.value});referenceText.value='';}await refresh();notice.value='Contenido vinculado al experto. Revise su procedencia y asígnelo como fuente primaria o complementaria.';});}
async function proposeProfile(){await action(async()=>{await api('/experts/'+foundationExpert.value+'/profile/draft',{session_id:await librarySession()});await refresh();notice.value='Borrador profesional generado a partir de las fuentes. Revíselo antes de aprobarlo.';});}
async function approveProfile(id){await action(async()=>{await api('/expert-profiles/'+id+'/approve',{approved:true});await refresh();notice.value='Perfil aprobado. Solo se usará mientras sus fuentes sigan disponibles y autorizadas.';});}
const foundationExpert=ref(null),foundationDocument=ref(null),foundationRole=ref('primary'),sourceAuthor=ref(''),sourceUrl=ref(''),sourceEdition=ref(''),sourceKind=ref('author_work'),sourceReviewed=ref(false);
watch(foundationExpert,()=>{activeReference.value=null;foundationDocument.value=null;referenceTitle.value='';referenceAuthor.value='';referenceUrl.value='';referenceText.value='';referencePdf.value=null;referenceConsent.value=false;sourceReviewed.value=false;expertSection.value='content';if(referencePdfInput.value)referencePdfInput.value.value='';});
const libraryExpert=computed(()=>catalog.value.expert.find(e=>e.id===foundationExpert.value));
const permanentDocuments=computed(()=>catalog.value.context.filter(d=>d.status==='ready'&&!d.expires_at&&d.permanent_consent));
const sourceTitle=id=>catalog.value.context.find(d=>d.id===id)?.title||'Fuente eliminada o no disponible';
function authorKey(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N} ]/gu,'').trim().replace(/\s+/g,' ');}
function primaryCount(e){return (e.primary_source_ids||[]).filter(id=>permanentDocuments.value.some(d=>d.id===id&&d.source?.reviewed_by_owner&&((d.source.kind==='official_documentation'&&d.source.source_url?.startsWith('https://'))||authorKey(d.source.author).includes(authorKey(e.inspiration_author||e.name))))).length;}
watch(foundationDocument,id=>{const source=catalog.value.context.find(d=>d.id===id)?.source||{};sourceAuthor.value=source.author||'';sourceUrl.value=source.source_url||'';sourceEdition.value=source.edition||'';sourceKind.value=source.kind||'author_work';sourceReviewed.value=false;});
async function configureFoundation(){await action(async()=>{await api('/contexts/'+foundationDocument.value+'/source',{author:sourceAuthor.value.trim(),source_url:sourceUrl.value.trim()||null,edition:sourceEdition.value.trim()||null,kind:sourceKind.value,reviewed_by_owner:sourceReviewed.value});const key=foundationRole.value==='primary'?'primary_source_ids':'complementary_source_ids';const ids=[...new Set([...(libraryExpert.value[key]||[]),foundationDocument.value])];await api('/experts/'+foundationExpert.value+'/sources',{document_ids:ids,role:foundationRole.value,approved:true});await refresh();notice.value='Fuente incorporada al fundamento del experto. Esto no equivale a verificar externamente su autoría.';});}
async function removeFoundation(id,role){await action(async()=>{const key=role==='primary'?'primary_source_ids':'complementary_source_ids';await api('/experts/'+foundationExpert.value+'/sources',{document_ids:(libraryExpert.value[key]||[]).filter(x=>x!==id),role,approved:true});await refresh();});}
const project=ref(null),board=ref(null),session=ref(null),transcript=ref([]),question=ref(''),title=ref(''),text=ref(''),scope=ref('SESSION'),consent=ref(false),selectedExperts=ref([]),file=ref(null),result=ref('');
const documentFileInput=ref(null);
const scopeOptions=[{title:'Solo esta consulta',value:'REQUEST'},{title:'Esta conversación · temporal',value:'SESSION'},{title:'Biblioteca del consejo',value:'BOARD'},{title:'Biblioteca de expertos',value:'EXPERT'},{title:'Biblioteca general',value:'GLOBAL'}];
const contextStatus={awaiting_upload:'Esperando archivo',queued:'Procesando',ready:'Disponible',failed:'No se pudo procesar'};
const retention=ref(24),memoryScope=ref('personal'),memoryConsent=ref(false),memoryText=ref('');
const expertName=ref(''),specialty=ref(''),principles=ref(''),skillIds=ref([]),repoPath=ref(''),repoId=ref(null),search=ref(''),connection=ref(null),connectionName=ref(''),connectionUrl=ref(''),readTools=ref(''),writeTools=ref(''),artifactKind=ref('requirement'),criteria=ref(''),target=ref('codex');
const relevantSessions=computed(()=>catalog.value.session.filter(s=>s.session_kind!=='library'));
const currentSession=computed(()=>catalog.value.session.find(s=>s.id===session.value));
const memoryCandidates=computed(()=>memoryRecords.value.filter(c=>c.status==='proposed'&&(!session.value||c.session_id===session.value)));
async function approveMemoryCandidate(id){await action(async()=>{await api('/memory-candidates/'+id+'/approve',{approved:true});await refresh();notice.value='Recuerdo guardado a largo plazo con su aprobación.';});}
async function dismissMemoryCandidate(id){await action(async()=>{await api('/memory-candidates/'+id+'/dismiss',{});await refresh();});}
const relevantArtifacts=computed(()=>catalog.value.artifact.filter(a=>!session.value||a.session_id===session.value));
const activeContexts=computed(()=>catalog.value.context.filter(c=>!session.value||c.session_id===session.value));
const activeBoard=computed(()=>catalog.value.board.find(b=>b.id===board.value));
async function api(path,body,method){const r=await fetch('/api'+path,{method:method||(body?'POST':'GET'),headers:{Authorization:'Bearer '+token.value,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));return d;}
async function action(fn){busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function refresh(){catalog.value=await api('/catalog');board.value ||= catalog.value.board[0]?.id;if(tab.value==='Memoria'){[memoryRecords.value,approvedMemoryRecords.value]=await Promise.all([api('/memory-candidates'),api('/approved-memories')]);}}
async function login(){await action(async()=>{await refresh();connected.value=true;if(localRequestedSession){const requested=catalog.value.session.find(s=>s.id===localRequestedSession);if(!requested)throw Error('La conversación solicitada no existe o no está disponible para este propietario.');project.value=requested.project_id;board.value=requested.board_id;session.value=requested.id;await refreshLocalCopies();tab.value='Compartir código';}});}
async function loadSession(){if(session.value){const s=catalog.value.session.find(s=>s.id===session.value);board.value=s.board_id;project.value=s.project_id;if(tab.value==='Compartir código')await refreshLocalCopies();}}
async function prepareDocuments(){await action(async()=>{session.value=await librarySession();scope.value='GLOBAL';consent.value=false;tab.value='Contexto';});}
async function context(){await action(async()=>{const c=await api('/contexts',{session_id:session.value,title:title.value,text:text.value,scope:scope.value,permanent_consent:consent.value,expert_ids:selectedExperts.value,retention_hours:Number(retention.value)});if(file.value){const f=file.value;const u=await api('/contexts/'+c.id+'/upload?content_type='+encodeURIComponent(f.type||'text/plain'),{});const form=new FormData();Object.entries(u.fields).forEach(([k,v])=>form.append(k,v));form.append('file',f);const r=await fetch(u.url,{method:'POST',body:form});if(!r.ok)throw Error('No se pudo cargar el archivo en Spaces');await api('/contexts/'+c.id+'/finalize',{});}title.value='';text.value='';file.value=null;if(documentFileInput.value)documentFileInput.value.value='';await refresh();notice.value='Documento guardado. Puede añadir el siguiente libro; el estado se actualizará automáticamente.';});}
async function createExpert(){await action(async()=>{await api('/experts',{name:expertName.value,specialty:specialty.value,principles:principles.value,skill_ids:skillIds.value});await refresh();notice.value='Experto creado';});}
async function createBoard(){await action(async()=>{await api('/boards',{name:title.value,mission:text.value,expert_ids:selectedExperts.value});await refresh();notice.value='Board creado';});}
async function skill(){await action(async()=>{await api('/skills',{name:title.value,content:text.value});await refresh();notice.value='Skill versionado';});}
async function artifact(){await action(async()=>{await api('/artifacts',{project_id:currentSession.value?.project_id,session_id:session.value,kind:artifactKind.value,title:title.value,content:text.value,acceptance_criteria:criteria.value.split('\n').filter(Boolean)});await refresh();notice.value='Borrador creado';});}
async function approve(a){await action(async()=>{await api('/artifacts/'+a.id+'/approve',{});await refresh();});}
async function exportPrompt(){await action(async()=>{result.value=(await api('/sessions/'+session.value+'/export?target='+target.value)).prompt;});}
async function addConnection(){await action(async()=>{await api('/connections',{name:connectionName.value,url:connectionUrl.value,expert_ids:selectedExperts.value,read_tools:readTools.value.split(',').map(s=>s.trim()).filter(Boolean),write_tools:writeTools.value.split(',').map(s=>s.trim()).filter(Boolean)});await refresh();});}
async function discover(){await action(async()=>{result.value=JSON.stringify(await api('/connections/'+connection.value+'/tools'),null,2);});}
async function generateDraft(){await action(async()=>{await api('/sessions/'+session.value+'/draft',{kind:artifactKind.value});await refresh();notice.value='Borrador generado. Revise el texto y apruebe solo cuando refleje lo acordado.';});}
function memoryTarget(){return memoryScope.value==='personal'?null:memoryScope.value==='board'?board.value:selectedExperts.value[0];}
async function saveMemory(){await action(async()=>{await api('/memories',{scope:memoryScope.value,target_id:memoryTarget(),text:memoryText.value,approved:memoryConsent.value});notice.value='Memoria aprobada incorporada';memoryText.value='';memoryConsent.value=false;});}
async function searchMemory(){await action(async()=>{result.value=JSON.stringify(await api('/memories/search',{scope:memoryScope.value,target_id:memoryTarget(),query:memoryText.value}),null,2);});}
async function importSkill(event){const f=event.target.files[0];if(!f)return;await action(async()=>{const form=new FormData();form.append('name',title.value||f.name);form.append('file',f);const r=await fetch('/api/skills/import',{method:'POST',headers:{Authorization:'Bearer '+token.value},body:form});if(!r.ok)throw Error('No se pudo importar el Skill');await refresh();notice.value='Skill importado';});}
watch(session,(value,old)=>{if(value!==old){clearLocalSelection();localCopies.value=[];}});
watch(tab,value=>{if(['Memoria','Decisiones'].includes(value)&&currentSession.value?.session_kind==='library')session.value=null;if(connected.value&&!busy.value)refresh().catch(e=>{error.value=e.message;});});
let uploadPoll=null;
watch([tab,connected],()=>{clearInterval(uploadPoll);if(connected.value&&['Contexto','Expertos'].includes(tab.value))uploadPoll=setInterval(()=>{if(!busy.value&&(catalog.value.context.some(c=>c.status==='queued')||catalog.value.reference?.some(r=>r.status==='queued'&&!r.content_available)))refresh().catch(()=>{});},4000);});
onUnmounted(()=>clearInterval(uploadPoll));
function download(){const u=URL.createObjectURL(new Blob([result.value],{type:'text/markdown'}));const a=document.createElement('a');a.href=u;a.download='vitruvius-development-prompt.md';a.click();URL.revokeObjectURL(u);}
</script>
<template>
<v-app><div class="shell"><aside><div class="brand">V<span>ITRUVIUS</span></div><p class="tagline">Think. Debate. Design. Decide.</p><nav aria-label="Navegación principal"><button v-for="item in [{key:'Inicio',label:'Mi consejo'},{key:'Expertos',label:'Fuentes de expertos'},{key:'Memoria',label:'Memoria'},{key:'Decisiones',label:'Especificaciones'}]" :class="{active:tab===item.key}" @click="tab=item.key;result=''">{{item.label}}</button><button class="advanced-toggle" @click="advanced=!advanced" :aria-expanded="advanced">{{advanced?'Cerrar herramientas':'Herramientas avanzadas'}}</button><template v-if="advanced"><p class="nav-help">Opcionales. Ábralas solo cuando las necesite.</p><button v-for="item in ['Contexto','Skills','Conexiones']" :class="{active:tab===item}" @click="tab=item;result=''">{{item==='Contexto'?'Documentos':item}}</button></template></nav><div class="sidebar-bottom">Tu consejo personal<br><small>Un espacio privado de criterio.</small></div></aside><main>
<header><div><p class="eyebrow">PERSONAL EXPERT COUNCIL</p><h1>{{displayTab}}</h1></div><v-chip color="secondary" variant="tonal">{{connected?'Sesión privada':'Acceso del propietario'}}</v-chip></header>
<v-alert v-if="error" type="error" class="mb-5" closable @click:close="error=''">{{error}}</v-alert><v-alert v-if="notice" type="success" class="mb-5">{{notice}}</v-alert>
<v-card v-if="!connected" class="login" rounded="xl"><h2>Bienvenido a Vitruvius</h2><p class="muted">Introduce tu token de propietario para abrir el espacio de trabajo.</p><v-text-field v-model="token" label="Token de acceso" type="password" autocomplete="off" @keyup.enter="login"/><v-btn color="primary" @click="login" :loading="busy">Abrir mi espacio</v-btn><p class="muted mt-5">El token se conserva solo durante esta visita. El servicio necesita PostgreSQL para iniciar una sesión.</p></v-card>
<template v-else>
<div v-if="['Decisiones','Memoria'].includes(tab)" class="session-filter"><v-select v-model="session" :items="relevantSessions" item-title="title" item-value="id" label="Filtrar por conversación (opcional)" clearable @update:model-value="loadSession"/></div>
<section v-if="tab==='Inicio'">
<v-card class="project-next"><p class="eyebrow">UN CONSEJO CUANDO LO NECESITE</p><h2>Invoque al consejo cuando lo necesite</h2><p>Desde Gemini, ChatGPT o Claude Code conectado a Vitruvius, plantee una pregunta o explore posibles soluciones. La charla puede terminar allí: no necesita convertirse en una especificación.</p><div class="next-actions"><div><h3>Explorar una idea</h3><p>«Quiero conversar con el consejo sobre cómo diseñar un agente». Contraste alternativas y continúe a su ritmo.</p></div><div><h3>Si aparece algo útil</h3><p>Vitruvius propone recuerdos que merece la pena conservar. Puede aprobarlos, descartarlos o pedir directamente «Guarda en memoria de largo plazo: …».</p></div></div><p class="muted">Solo si usted lo pide, una conversación se convierte en un borrador de especificación. Revise y apruebe la versión antes de exportarla para implementar.</p><details class="council-details"><summary>Conexión del cliente</summary><p>MCP: <code>https://vitruvius.work/mcp/</code>. El cliente debe admitir la conexión y la autenticación del propietario. No pegue tokens en el chat. Pida invocar al consejo desde su cliente.</p></details></v-card>
<v-card class="form-card mt-6"><h2>{{activeBoard?.name||'Consejo de expertos'}}</h2><v-select v-if="catalog.board.length>1" v-model="board" :items="catalog.board" item-title="name" item-value="id" label="Consejo que quiere revisar"/><div class="panelists"><div v-for="e in catalog.expert.filter(e=>activeBoard?.expert_ids.includes(e.id))" :key="e.id" class="panelist"><strong>{{e.name}}</strong><small>{{e.specialty}}</small><small :class="primaryCount(e)?'grounded-label':'missing-label'">{{primaryCount(e)?'Fuentes primarias disponibles':'Pendiente incorporar fuentes'}}</small></div></div><p class="muted">Son analistas virtuales con fuentes documentadas, no las personas reales. Una perspectiva sin fundamento revisado se abstiene de emitir opiniones técnicas.</p><v-btn variant="text" @click="tab='Expertos'">Revisar fuentes de los expertos</v-btn></v-card>
<v-card v-if="relevantSessions.length" class="form-card mt-6"><h2>Resultados de sus conversaciones</h2><p class="muted">Conversar no obliga a producir nada. Aquí puede revisar los recuerdos propuestos y las especificaciones que sí hayan surgido.</p><div v-for="s in relevantSessions.slice().reverse().slice(0,12)" :key="s.id" class="record-card"><h3>{{s.title}}</h3><p>{{catalog.artifact.filter(a=>a.session_id===s.id).length}} borradores o especificaciones · {{(catalog.memory_candidate||[]).filter(c=>c.session_id===s.id&&c.status==='proposed').length}} recuerdos propuestos</p><v-btn v-if="catalog.artifact.some(a=>a.session_id===s.id)" variant="text" @click="session=s.id;tab='Decisiones'">Revisar especificaciones</v-btn><v-btn v-if="(catalog.memory_candidate||[]).some(c=>c.session_id===s.id&&c.status==='proposed')" variant="text" @click="session=s.id;tab='Memoria'">Revisar recuerdos</v-btn></div></v-card>
</section>
<section v-if="tab==='Compartir código'" class="local-code-share">
<v-card class="form-card"><p class="eyebrow">CONTINÚE EN EL MISMO CHAT</p><h2>Comparta una carpeta de código</h2><p>Seleccione el repositorio descargado en este computador. No necesita publicarlo en GitHub ni configurar rutas en un panel.</p><p class="muted">Solo se comparte una copia de los archivos autorizados, disponible para esta conversación durante 24 horas. No se ejecuta ni modifica código. Para reflejar cambios posteriores, vuelva a compartir la carpeta.</p>
<label class="file-label local-folder-picker">Elegir carpeta del computador<input ref="localFolderInput" type="file" webkitdirectory directory multiple @change="chooseLocalFolder" :disabled="busy" aria-label="Elegir carpeta de código"/></label>
<div v-if="localSelection"><h3>{{localSelection.name}}</h3><p>{{localSelection.entries.length}} archivos de texto disponibles · {{localSelection.excluded}} excluidos por tipo, nombre o tamaño · {{localSelection.omitted}} fuera del índice máximo.</p><details class="council-details"><summary>Revisar y excluir archivos antes de compartir</summary><p>Máximo 500 archivos de texto, 200 KB por archivo y dos millones de caracteres en total. Si se alcanza el presupuesto, la copia se marca como parcial.</p><div class="local-file-list"><label v-for="e in localSelection.entries" :key="e.path"><input type="checkbox" v-model="localSelectedPaths" :value="e.path" :disabled="busy"/> {{e.path}}</label></div></details><p class="muted">Se excluyen carpetas ocultas, dependencias y archivos sensibles habituales. También se omiten archivos cuyo contenido parezca incluir claves. Estos filtros no garantizan detectar todos los secretos: revise la selección y comparta solo código autorizado. No se interpreta .gitignore.</p><v-checkbox v-model="localConsent" label="Autorizo enviar estos archivos al servidor privado de Vitruvius y los fragmentos consultados al modelo mediante OpenRouter. Las citas y respuestas pueden permanecer en el historial." :disabled="busy"/><v-btn color="primary" @click="shareLocalCopy" :loading="busy" :disabled="busy||!localConsent||!localSelectedPaths.length">Compartir copia temporal</v-btn><v-btn variant="text" @click="clearLocalSelection" :disabled="busy">Descartar selección</v-btn></div>
<p v-if="localProgress" role="status" class="mt-4">{{localProgress}}</p><p class="muted mt-5">Seleccionar la carpeta no envía su contenido. La carga comienza únicamente al pulsar «Compartir copia temporal». El acceso se pierde al recargar la página; la copia enviada sigue disponible hasta que expire o la desconecte.</p></v-card>
<v-card v-for="copy in localCopies" :key="copy.id" class="record-card mt-5"><h3>{{copy.name}}</h3><v-chip :color="copy.partial?'warning':'secondary'">{{copy.partial?'Copia parcial':'Copia de la selección compartida'}}</v-chip><p>{{copy.file_count}} archivos · disponible hasta {{new Date(copy.expires_at).toLocaleString()}}</p><details class="council-details"><summary>Ver archivos que el consejo puede consultar</summary><div class="local-file-list"><span v-for="f in copy.files" :key="f.path">{{f.path}} · {{f.lines}} líneas</span></div></details><p>Ya puede volver a Claude, ChatGPT o Gemini y pedir que consulte esta copia en la misma conversación de Vitruvius.</p><v-btn variant="outlined" @click="disconnectLocalCopy(copy.id)" :disabled="busy">Desconectar y eliminar esta copia</v-btn></v-card><v-btn class="mt-5" variant="text" @click="tab='Inicio'">Volver a mi consejo</v-btn>
</section>
<section v-if="tab==='Contexto'"><v-btn variant="text" class="mb-4" @click="tab='Inicio'">Volver a mi consejo</v-btn><v-alert v-if="!session" type="info" variant="tonal" class="mb-5">Puede incorporar fuentes a su biblioteca sin iniciar una charla con los expertos.<div class="mt-3"><v-btn color="primary" @click="prepareDocuments" :disabled="busy">Preparar carga de documentos</v-btn></div></v-alert><div v-if="session" class="two-col"><v-card class="form-card"><h2>Cargar libros y documentos</h2><v-alert type="info" variant="tonal" class="mb-4">Cargar una fuente y dar acceso al consejo no la convierte automáticamente en el fundamento de un experto. Configure esa relación en Expertos. El autor del libro no tiene que pertenecer al consejo.</v-alert><p class="muted">Elija un archivo y decida si debe conservarse en una biblioteca o utilizarse de forma temporal.</p><v-text-field v-model="title" label="Título"/><v-textarea v-model="text" label="Texto adicional"/><v-text-field v-if="['REQUEST','SESSION'].includes(scope)" v-model="retention" type="number" min="1" max="720" label="Retención temporal (horas)"/><v-select v-model="scope" :items="scopeOptions" label="Dónde estará disponible"/><v-select v-model="selectedExperts" :items="catalog.expert" item-title="name" item-value="id" multiple label="Restringir acceso a panelistas (opcional)" hint="Es un permiso de lectura, no una asignación de autoría ni de fundamento. Déjelo vacío para compartir según la biblioteca elegida." persistent-hint/><v-checkbox v-if="!['REQUEST','SESSION'].includes(scope)" v-model="consent" label="Autorizo conservar este conocimiento"/><label class="file-label">Archivo PDF, texto o Markdown<input ref="documentFileInput" type="file" accept=".pdf,.txt,.md" @change="file=$event.target.files[0]"/></label><v-btn color="primary" @click="context" :disabled="!session||!title.trim()||busy||(!text.trim()&&!file)||(!['REQUEST','SESSION'].includes(scope)&&!consent)||(scope==='EXPERT'&&!selectedExperts.length)">Guardar documento</v-btn></v-card><div><div class="document-list-heading"><h2>Documentos incorporados</h2><v-btn variant="text" size="small" @click="action(refresh)" :disabled="busy">Actualizar estado</v-btn></div><p v-if="!activeContexts.length" class="muted">Aquí verá sus documentos y el avance del procesamiento.</p><v-card v-for="c in activeContexts" class="record-card"><h3>{{c.title}}</h3><v-chip size="small">{{scopeOptions.find(s=>s.value===c.scope)?.title}} · {{contextStatus[c.status]||c.status}}</v-chip><p>{{c.expires_at?'Expira: '+new Date(c.expires_at).toLocaleString():'Conservación permanente autorizada'}}</p><v-btn size="small" variant="text" @click="action(async()=>{await api('/contexts/'+c.id,undefined,'DELETE');await refresh()})">Eliminar</v-btn><v-btn v-if="c.expires_at" size="small" variant="text" @click="action(async()=>{await api('/contexts/'+c.id+'/promote?scope=BOARD',{});await refresh()})">Conservar en biblioteca del consejo</v-btn></v-card></div></div></section>
<section v-if="tab==='Memoria'"><h2>Lo que merece recordarse</h2><p class="muted">Vitruvius identifica posibles preferencias duraderas, lecciones y decisiones. Una propuesta todavía no es memoria de largo plazo. Usted puede aprobarla, descartarla o pedir que se guarde un texto explícito desde el cliente.</p><div class="two-col"><div><h3>Recuerdos propuestos</h3><p v-if="!memoryCandidates.length">No hay propuestas pendientes. Una conversación exploratoria puede no dejar ningún recuerdo.</p><v-card v-for="c in memoryCandidates" :key="c.id" class="record-card"><v-chip size="small" color="warning">Propuesto · no guardado</v-chip><p>{{c.text}}</p><p class="muted">Por qué podría servir: {{c.reason}}</p><details class="council-details"><summary>Ver declaración que origina la propuesta</summary><blockquote v-for="e in c.evidence">{{e.quote}}</blockquote></details><v-btn color="primary" @click="approveMemoryCandidate(c.id)" :disabled="busy">Aprobar y recordar</v-btn><v-btn variant="text" @click="dismissMemoryCandidate(c.id)" :disabled="busy">Descartar</v-btn></v-card></div><div><h3>Memoria aprobada</h3><v-card v-for="m in approvedMemoryRecords.filter(m=>!session||m.session_id===session)" :key="m.id" class="record-card"><v-chip color="secondary" size="small">Guardado con autorización</v-chip><p>{{m.text||'Recuerdo anterior: consulte su contenido desde el cliente conectado.'}}</p><p class="muted">{{m.scope_label==='conversation'?'De esta conversación':m.scope==='personal'?'Conocimiento del propietario':m.scope==='board'?'Del consejo':'Ámbito conservado de una versión anterior'}}</p><v-btn size="small" variant="text" @click="action(async()=>{await api('/memories/'+m.id,undefined,'DELETE');await refresh()})">Eliminar recuerdo</v-btn></v-card><p class="muted">La memoria aporta contexto para futuras charlas; no sustituye las fuentes de los expertos. Los adjuntos y las copias de código temporales no se convierten automáticamente en recuerdos.</p></div></div></section>
<section v-if="tab==='Expertos'">
<v-card class="form-card mb-6 expert-foundation"><h2>Prepare una perspectiva cuando la necesite</h2><p>No es un paso para cada conversación. Se hace al incorporar un experto o añadir nuevas fuentes: vincule contenido, revise su fundamento y, si lo desea, apruebe un perfil profesional.</p><p class="muted">Un panelista necesita fuentes primarias para emitir opiniones técnicas. Sus nombres, la memoria y los conocimientos generales del modelo no sustituyen una biblioteca. La autoría y procedencia que registre deben ser revisadas por usted; no se verifican automáticamente en Internet.</p><v-select v-model="foundationExpert" :items="catalog.expert" item-title="name" item-value="id" label="Experto cuya biblioteca quiere configurar"/>
<template v-if="libraryExpert">
<v-tabs v-model="expertSection" color="primary" class="mb-5"><v-tab value="content">Contenido vinculado</v-tab><v-tab value="foundation">Fundamento</v-tab><v-tab value="profile">Perfil profesional</v-tab></v-tabs><v-alert v-if="!primaryCount(libraryExpert)" type="warning" variant="tonal" class="mb-5">Sin fuentes primarias revisadas: este experto no emitirá opiniones técnicas ni tendrá un perfil generado.</v-alert>
<div v-if="expertSection==='content'" class="reference-library"><h3>Contenido vinculado a {{libraryExpert.name}}</h3><p class="muted">Registre publicaciones de la persona, artículos, PDF o videos. El autor de la fuente se registra por separado: nunca se deduce del nombre del experto.</p><div class="two-col"><div><v-text-field v-model="referenceTitle" label="Título de la fuente"/><v-text-field v-model="referenceAuthor" label="Autor o responsable real del contenido"/><v-select v-model="referenceKind" :items="[{title:'Artículo web',value:'article'},{title:'Publicación de X',value:'x_post'},{title:'PDF de artículo o libro',value:'pdf'},{title:'Video de YouTube',value:'youtube'}]" label="Tipo de contenido"/><v-text-field v-model="referenceUrl" :label="referenceKind==='pdf'?'URL del PDF (opcional si cargará un archivo)':'Enlace directo al contenido'"/><v-btn color="primary" @click="registerReference" :disabled="busy||!referenceTitle.trim()||!referenceAuthor.trim()||(referenceKind!=='pdf'&&!referenceUrl.trim())">Guardar referencia</v-btn></div><div><v-alert type="info" variant="tonal" class="mb-4">Un enlace registrado no significa contenido leído. X y YouTube requieren que aporte el texto, una transcripción con tiempos o un PDF autorizado en esta versión.</v-alert><v-checkbox v-model="referenceConsent" label="Autorizo conservar el contenido que importe en la biblioteca de este experto"/><v-select v-model="activeReference" :items="expertReferences.filter(r=>!r.document_id)" item-title="title" item-value="id" label="Referencia a la que aportará contenido"/><v-textarea v-model="referenceText" label="Texto del artículo, publicación o transcripción" hint="Para videos, conserve las marcas de tiempo del material original." persistent-hint rows="5"/><label class="file-label">O aporte un PDF del contenido<input ref="referencePdfInput" type="file" accept=".pdf" @change="referencePdf=$event.target.files[0]"/></label><v-btn variant="outlined" @click="attachReferenceContent" :disabled="busy||!activeReference||!referenceConsent||(!referenceText.trim()&&!referencePdf)">Incorporar contenido</v-btn></div></div>
<div class="document-list-heading mt-5"><h3>Referencias registradas</h3><v-btn variant="text" @click="action(refresh)" :disabled="busy">Actualizar estados</v-btn></div><p v-if="!expertReferences.length" class="muted">Este experto todavía no tiene referencias vinculadas.</p><v-card v-for="r in expertReferences" :key="r.id" class="record-card"><v-chip size="small">{{referenceNames[r.kind]}} · {{referenceStatus(r)}}</v-chip><h3>{{r.title}}</h3><p>Autor registrado: {{r.author}}</p><a v-if="r.url" :href="r.url" target="_blank" rel="noopener noreferrer">Ver procedencia original</a><p v-if="r.message" class="muted">{{r.message}}</p><v-btn v-if="r.url&&['article','pdf'].includes(r.kind)&&!r.document_id&&r.status!=='queued'" variant="outlined" @click="importReference(r.id)" :disabled="busy||!referenceConsent">Importar contenido público</v-btn><v-btn v-if="r.content_available" variant="tonal" color="primary" @click="foundationDocument=r.document_id;expertSection='foundation'">Revisar y asignar al fundamento</v-btn></v-card></div>
<div v-if="expertSection==='foundation'"><h3 class="mt-6">Biblioteca de fundamento</h3><v-alert :type="primaryCount(libraryExpert)?'info':'warning'" variant="tonal" class="mb-4">{{primaryCount(libraryExpert)?'Tiene fuentes primarias configuradas. Cada respuesta seguirá necesitando evidencia pertinente y revisión.':'Sin fuentes primarias: este panelista no emitirá opiniones técnicas.'}}</v-alert><div class="two-col"><div><h3>Fuentes primarias</h3><p class="muted">Obra del autor que inspira al panelista o documentación técnica oficial de referencia. La documentación de un equipo no equivale a una opinión personal del autor.</p><div v-for="id in libraryExpert.primary_source_ids||[]" class="library-source">{{sourceTitle(id)}}<v-btn size="small" variant="text" @click="removeFoundation(id,'primary')" :disabled="busy">Quitar del fundamento</v-btn></div><p v-if="!libraryExpert.primary_source_ids?.length">Sin fuentes primarias.</p><h3>Bibliografía complementaria</h3><p class="muted">Otros autores pueden ampliar o contradecir el análisis. Sus afirmaciones se atribuyen a esas fuentes, no a la persona que da nombre al panelista.</p><div v-for="id in libraryExpert.complementary_source_ids||[]" class="library-source">{{sourceTitle(id)}}<v-btn size="small" variant="text" @click="removeFoundation(id,'complementary')" :disabled="busy">Quitar del fundamento</v-btn></div></div><div><v-select v-model="foundationDocument" :items="permanentDocuments" item-title="title" item-value="id" label="Documento permanente ya procesado"/><p v-if="!permanentDocuments.length" class="muted">Primero incorpore una fuente permanente desde Contenido vinculado o Documentos. La carga por sí sola no configura un experto.</p><v-select v-model="foundationRole" :items="[{title:'Fuente primaria',value:'primary'},{title:'Bibliografía complementaria',value:'complementary'}]" label="Función dentro de la biblioteca"/><v-text-field v-model="sourceAuthor" label="Autor o entidad responsable de la fuente"/><v-select v-model="sourceKind" :items="[{title:'Obra de autor',value:'author_work'},{title:'Documentación técnica oficial',value:'official_documentation'},{title:'Otra fuente',value:'other'}]" label="Tipo de procedencia"/><v-text-field v-model="sourceUrl" label="Enlace de procedencia (obligatorio para documentación oficial)"/><v-text-field v-model="sourceEdition" label="Edición o versión (opcional)"/><v-checkbox v-model="sourceReviewed" label="He revisado la autoría y procedencia de esta fuente"/><v-btn color="primary" @click="configureFoundation" :disabled="busy||!foundationDocument||!sourceAuthor.trim()||!sourceReviewed||(sourceKind==='official_documentation'&&!sourceUrl.startsWith('https://'))">Confirmar fuente y añadir al fundamento</v-btn></div></div>
</div><div v-if="expertSection==='profile'" class="professional-profile mt-6"><h3>Perfil profesional documentado</h3><p class="muted">Se construye con principios, criterios, métodos y formas de argumentar respaldados en las fuentes primarias. Es una interpretación profesional revisable, no una personalidad psicológica ni una representación auténtica de la persona.</p><v-btn color="primary" variant="tonal" @click="proposeProfile" :disabled="busy||!primaryCount(libraryExpert)">Proponer perfil desde las fuentes primarias</v-btn><v-card v-for="p in expertProfiles" :key="p.id" class="record-card mt-4"><v-chip :color="p.status==='approved'?'secondary':'warning'" size="small">{{p.status==='approved'?'Perfil aprobado':'Borrador · no se usa todavía'}} · {{p.project_id?'Solo en su ámbito de origen':'Biblioteca del experto'}}</v-chip><div v-for="(claim,index) in p.claims"><h4 class="mt-4">{{claim.kind==='source'?'Lo que dice la fuente':'Interpretación propuesta'}}</h4><p>{{claim.text}}</p><div v-for="c in p.citations.filter(c=>c.claim_index===index)" class="citation"><strong>{{c.title}} · {{c.source?.author}} · {{c.page?'p. '+c.page:'fragmento'}}</strong><blockquote>{{c.quote}}</blockquote></div></div><v-btn v-if="p.status==='draft'" class="mt-4" color="primary" @click="approveProfile(p.id)" :disabled="busy">Aprobar y usar este perfil</v-btn></v-card></div></template></v-card><details class="council-details"><summary>Opcional: crear otro experto o consejo</summary><div class="two-col"><v-card class="form-card"><h2>Construir un experto</h2><v-text-field v-model="expertName" label="Nombre persistente"/><v-text-field v-model="specialty" label="Especialidad"/><v-textarea v-model="principles" label="Principios y método"/><v-select v-model="skillIds" :items="catalog.skill" item-title="name" item-value="id" multiple label="Skills"/><v-btn color="primary" @click="createExpert" :disabled="busy||!expertName||!specialty">Crear experto</v-btn></v-card><v-card class="form-card"><h2>Constituir un Board</h2><v-text-field v-model="title" label="Nombre del Board"/><v-textarea v-model="text" label="Misión"/><v-select v-model="selectedExperts" :items="catalog.expert" item-title="name" item-value="id" multiple label="Panelistas"/><v-btn color="primary" @click="createBoard" :disabled="busy||!title||!selectedExperts.length">Crear Board</v-btn></v-card></div></details></section>
<section v-if="tab==='Skills'" class="two-col"><v-card class="form-card"><h2>Registrar Skill</h2><label class="file-label">Importar SKILL.md o ZIP<input type="file" accept=".md,.zip" @change="importSkill"/></label><v-text-field v-model="title" label="Nombre"/><v-textarea v-model="text" label="Contenido de SKILL.md" rows="12"/><v-btn color="primary" @click="skill" :disabled="busy||!title||!text">Guardar versión</v-btn></v-card><div><v-card v-for="s in catalog.skill" class="record-card"><h3>{{s.name}} <small>v{{s.version}}</small></h3><p class="pre">{{s.content}}</p></v-card></div></section>
<section v-if="tab==='Decisiones'"><h2>De una conversación a una especificación</h2><p class="muted">Solo aparecen documentos cuando usted pide generarlos desde su cliente. Revise el borrador y apruebe la versión que refleje lo acordado. Puede conversar con el consejo sin producir ninguno.</p><p v-if="!relevantArtifacts.length">Todavía no hay especificaciones para esta selección. Para crear una, pídalo en la conversación con el consejo.</p><v-card v-for="a in relevantArtifacts" :key="a.id" class="record-card"><v-chip size="small" :color="a.status==='approved'?'secondary':'warning'">{{a.status==='approved'?'Aprobado':'Borrador'}} · v{{a.version}}</v-chip><h3>{{a.title}}</h3><p class="pre">{{a.content}}</p><ul><li v-for="c in a.acceptance_criteria">{{c}}</li></ul><v-btn v-if="a.status!=='approved'" class="mt-4" @click="approve(a)" :disabled="busy">Aprobar esta versión</v-btn></v-card><v-card v-if="relevantArtifacts.length" class="form-card"><h3>Entregar a implementación</h3><p>Seleccione la conversación de origen y apruebe sus versiones actuales antes de exportar. También puede pedir la entrega desde el cliente.</p><v-select v-model="target" :items="['codex','claude-code']" label="Destino"/><v-btn color="primary" @click="exportPrompt" :disabled="busy||!session">Exportar instrucciones de implementación</v-btn></v-card></section>
<section v-if="tab==='Conexiones'" class="two-col"><v-card class="form-card"><h2>Herramientas MCP</h2><p class="muted">El propietario debe autorizar previamente el origen HTTPS en el servidor. Las acciones de escritura requieren una aprobación para los argumentos exactos.</p><v-text-field v-model="connectionName" label="Nombre"/><v-text-field v-model="connectionUrl" label="URL HTTPS del servidor MCP"/><v-select v-model="selectedExperts" :items="catalog.expert" item-title="name" item-value="id" multiple label="Expertos autorizados"/><v-text-field v-model="readTools" label="Herramientas de lectura, separadas por coma"/><v-text-field v-model="writeTools" label="Herramientas de escritura, separadas por coma"/><v-btn @click="addConnection" :disabled="busy||!connectionName||!connectionUrl">Registrar conexión</v-btn></v-card><v-card class="form-card"><h2>Descubrir herramientas</h2><div v-for="r in catalog.tool_request" class="record-card"><h3>{{r.tool}}</h3><p>Revisa los argumentos antes de autorizar la acción.</p><pre>{{JSON.stringify(r.arguments,null,2)}}</pre><v-btn color="primary" @click="action(async()=>{result=JSON.stringify(await api('/tool-requests/'+r.id+'/execute',{}),null,2);await refresh()})" :disabled="busy">Aprobar y ejecutar estos argumentos</v-btn></div><v-select v-model="connection" :items="catalog.connection" item-title="name" item-value="id" label="Conexión"/><v-btn color="primary" @click="discover" :disabled="busy||!connection">Consultar servidor</v-btn><p class="muted mt-5">MCP entrante: /mcp/ · Autenticación Bearer del propietario. La compatibilidad depende de las capacidades del cliente.</p></v-card></section>
<v-card v-if="result" class="form-card mt-6"><div class="result-header"><h2>Resultado</h2><v-btn @click="download">Descargar</v-btn></div><pre>{{result}}</pre></v-card>
</template><footer>VITRUVIUS · Las conclusiones son propuestas hasta que tú las apruebes.</footer></main></div></v-app>
</template>
